  id, title, report_type, executive_summary, analytical_deep_dive,
  key_takeaways, original_sources, tags, matched_lenses
) VALUES (
  '430f2684-15a2-5ef5-9445-56d1ad15241d',
  '플린트(Flint): AI 시대를 위한 시각화 언어',
  '빅테크 공식',
  '한눈에 보기 간단한 사양에서 세련된 차트를 살펴보세요. Flint를 사용하면 AI 에이전트가 사람이 편집할 수 있는 간단한 사양에서 표현력이 풍부하고 시각적으로 세련된 차트를 안정적으로 생성할 수 있습니다. 의미 유형 가이드 디자인. Flint는 의미론적 데이터 유형을 활용하여 데이터의 의미를 표현합니다. 이는 컴파일러가 적절한 배율, 기준선, 서식 및 색 구성표를 선택하는 데 도움이 됩니다. 레이아웃은 데이터에 맞게 조정됩니다. Flint는 크기 조정, 간격, 레이블 및 레이아웃을 자동으로 관리하므로 명시적인 사용자 구성 없이도 카디널리티 및 밀도 변경 시 차트를 계속 읽을 수 있습니다. 하나의 사양이 여러 백엔드를 대상으로 할 수 있습니다. 싱글',
  '# 📌 [Technical Report] 플린트(Flint): AI 시대를 위한 시각화 언어

> **주요 출처**: Microsoft Research | **카테고리**: 빅테크 공식 | **검증**: ✅ AI Trend News

