* **💼 비즈니스**: 고비용 상용 API를 오픈소스 모델로 대체하여 TCO를 최적화하세요.
* **🔬 연구자**: 관련 벤치마크 데이터 및 논문 원문을 교차 검증하세요.
',
  '["한눈에 보기 간단한 사양에서 세련된 차트를 살펴보세요.", "Flint를 사용하면 AI 에이전트가 사람이 편집할 수 있는 간단한 사양에서 표현력이 풍부하고 시각적으로 세련된 차트를 안정적으로 생성할 수 있습니다.", "Flint는 의미론적 데이터 유형을 활용하여 데이터의 의미를 표현합니다."]',
