---

### 1. 📌 핵심 요약

오늘날의 AI 에이전트는 과거 상호 작용을 기억하지 않습니다.

관련 정보를 반복적으로 제공하거나 외부 소스에서 이를 검색해야 하는데, 이는 더 길고 복잡한 작업을 처리함에 따라 효율성이 떨어집니다.

상담원의 역량을 확장하려면 시간이 지남에 따라 정보를 유지하고 액세스할 수 있는 보다 효율적인 방법이 필요합니다.

---

### 2. 🔍 배경 및 의미

오늘날의 AI 에이전트는 과거 상호 작용을 기억하지 않습니다. 관련 정보를 반복적으로 제공하거나 외부 소스에서 이를 검색해야 하는데, 이는 더 길고 복잡한 작업을 처리함에 따라 효율성이 떨어집니다. 상담원의 역량을 확장하려면 시간이 지남에 따라 정보를 유지하고 액세스할 수 있는 보다 효율적인 방법이 필요합니다. Memora는 저장된 것(풍부한 메모리 콘텐츠)과 검색 방법(경량 추상화 및 큐 앵커)을 분리하고 추상화와 특이성의 균형을 유지함으로써 장거리 작업에서 에이전트 생산성을 극적으로 높이는 확장 가능한 메모리 시스템입니다. 메모라 세트

