  '56d47f36-a15d-5965-b84f-130eefd37cf5',
  'Microsoft 365용 Amazon Quick: 작업하는 곳에서의 에이전트적 AI',
  '빅테크 공식',
  '기업 데이터는 수십 개의 시스템에 있지만 작업은 Microsoft 365에서 이루어지는 경우가 많습니다. Amazon Quick은 데이터에 기반을 둔 AI 보조자로서 격차를 해소하며 이제 Microsoft Word, Excel, PowerPoint 및 Outlook 내에서 직접 사용할 수 있습니다. 이러한 확장 기능을 사용하면 새로운 애플리케이션을 채택하거나 작업 방식을 변경할 필요가 없습니다. 대신 팀이 매일 아침 여는 Microsoft 365 앱에 Amazon Quick 연결 데이터 액세스 및 에이전트 문서 편집 기능을 직접 제공합니다. 이제 Amazon Quick Sight 대시보드, Spaces, AWS 데이터 소스 및 타사 통합에 별도의 비용 없이 액세스할 수 있습니다.',
  '# 📌 [Technical Report] Microsoft 365용 Amazon Quick: 작업하는 곳에서의 에이전트적 AI

> **주요 출처**: AWS Machine Learning | **카테고리**: 빅테크 공식 | **검증**: ✅ AI Trend News

---

### 1. 📌 핵심 요약

기업 데이터는 수십 개의 시스템에 있지만 작업은 Microsoft 365에서 이루어지는 경우가 많습니다.

Amazon Quick은 데이터에 기반을 둔 AI 보조자로서 격차를 해소하며 이제 Microsoft Word, Excel, PowerPoint 및 Outlook 내에서 직접 사용할 수 있습니다.

이러한 확장 기능을 사용하면 새로운 애플리케이션을 채택하거나 작업 방식을 변경할 필요가 없습니다.

---

### 2. 🔍 배경 및 의미

기업 데이터는 수십 개의 시스템에 있지만 작업은 Microsoft 365에서 이루어지는 경우가 많습니다. Amazon Quick은 데이터에 기반을 둔 AI 보조자로서 격차를 해소하며 이제 Microsoft Word, Excel, PowerPoint 및 Outlook 내에서 직접 사용할 수 있습니다. 이러한 확장 기능을 사용하면 새로운 애플리케이션을 채택하거나 작업 방식을 변경할 필요가 없습니다. 대신 팀이 매일 아침 여는 Microsoft 365 앱에 Amazon Quick 연결 데이터 액세스 및 에이전트 문서 편집 기능을 직접 제공합니다. 이제 Amazon Quick Sight 대시보드, Spaces, AWS 데이터 소스 및 타사 통합에 별도의 비용 없이 액세스할 수 있습니다.

---

