  '["기업 데이터는 수십 개의 시스템에 있지만 작업은 Microsoft 365에서 이루어지는 경우가 많습니다.", "Amazon Quick은 데이터에 기반을 둔 AI 보조자로서 격차를 해소하며 이제 Microsoft Word, Excel, PowerPoint 및 Outlook 내에서 직접 사용할 수 있습니다.", "이러한 확장 기능을 사용하면 새로운 애플리케이션을 채택하거나 작업 방식을 변경할 필요가 없습니다."]',
