  '빅테크 공식',
  '1부에서는 Amazon Bedrock에 대한 세분화된 비용 귀속을 소개했습니다. 이 기능은 호출을 수행한 IAM 주체에 대한 모든 추론 요청을 자동으로 추적합니다. 새로운 line_item_iam_principal 열이 어떻게 사용자별 및 애플리케이션별 가시성을 제공할 수 있는지 보여주었습니다. 선택적 비용 할당 태그를 사용하면 AWS Cost Explorer를 사용하여 팀, 프로젝트 또는 테넌트별 지출을 집계할 수도 있습니다. 이 접근 방식을 사용하면 일반적으로 Claude Code 또는 Codex와 같은 타사 도구 또는 자체 사용자 지정 빌드에 관계없이 Bedrock 기반 서비스 또는 애플리케이션에 대해 원하는 세분성으로 사용량을 추적할 수 있습니다. 목',
