  '["대규모 언어 모델(LLM) 추론을 대규모로 실행하면 일반적으로 KV 캐시 절충안이 발생합니다.", "증가하는 KV 캐시를 수용하기 위해 대형 GPU 인스턴스에 대한 비용을 지불하거나 모든 요청에 ​​대해 동일한 프롬프트가 다시 계산되므로 느린 TTFT(첫 번째 토큰까지의 시간)를 허용합니다.", "비즈니스 라인별 엔드포인트, RAG(Retrieval Augmented Generation) 파이프라인 또는 다중 턴 대화 애플리케이션 전반에 걸쳐 Qwen, Llama, DeepSeek 등과 같이 공개적으로 사용 가능한 FM(기반 모델)의 광범위한 카탈로그를 배포하는 팀의 경우 이러한 절충안은 직접적으로 더 높은 인프라 비용으로 이어지고 우리의 성능을 저하시킵니다.."]',
