',
  '["사이버 방어자들은 지금까지 이보다 더 많은 기능을 사용할 수 없었고 더 이상 필요하지도 않았습니다.", "이제 프론티어 모델은 전체 코드 기반을 추론하고 근본 원인에 대한 취약점을 추적하며 몇 분 안에 수정 사항을 제안할 수 있습니다.", "적들도 동일한 기능을 사용할 수 있습니다."]',
