INSERT OR REPLACE INTO trend_news (
  id, title, report_type, executive_summary, analytical_deep_dive,
  key_takeaways, original_sources, tags, matched_lenses
) VALUES (
  '2b8edf24-7fe2-58bc-9a17-2b80ea994d16',
  'ONESTRUCTION이 AWS GenAIIC를 사용하여 Ishigaki-IDS 기반 모델을 구축한 방법',
  '빅테크 공식',
  '이 게시물은 ONESTRUCTION, Inc.와 Amazon Web Services Japan G.K가 공동 작성했습니다. GENIAC(Generative AI Accelerator Challenge) 3단계의 일환으로 AWS GenAIIC(AWS Generative AI Innovation Center)의 기술 자문을 받았습니다. 데이터가 부족한 분야에서 도메인 전문 기반 모델을 구축하는 것은 어렵습니다. 충분한 훈련 데이터, 전문 지식, 출력을 검증할 방법이 필요합니다. ONESTRUCTION, Inc.는 openBIM을 통해 업계 문제를 해결하는 건설 기술 스타트업입니다. GenAIIC의 기술 자문을 받아 전문 기반 모델(FM)인 Ishigaki-IDS를 구축했습니다.',
  '# 📌 [Technical Report] ONESTRUCTION이 AWS GenAIIC를 사용하여 Ishigaki-IDS 기반 모델을 구축한 방법

> **주요 출처**: AWS Machine Learning | **카테고리**: 빅테크 공식 | **검증**: ✅ AI Trend News

---

### 1. 📌 핵심 요약

이 게시물은 ONESTRUCTION, Inc.와 Amazon Web Services Japan G.K가 공동 작성했습니다.

GENIAC(Generative AI Accelerator Challenge) 3단계의 일환으로 AWS GenAIIC(AWS Generative AI Innovation Center)의 기술 자문을 받았습니다.

데이터가 부족한 분야에서 도메인 전문 기반 모델을 구축하는 것은 어렵습니다.

---

### 2. 🔍 배경 및 의미

이 게시물은 ONESTRUCTION, Inc.와 Amazon Web Services Japan G.K가 공동 작성했습니다. GENIAC(Generative AI Accelerator Challenge) 3단계의 일환으로 AWS GenAIIC(AWS Generative AI Innovation Center)의 기술 자문을 받았습니다. 데이터가 부족한 분야에서 도메인 전문 기반 모델을 구축하는 것은 어렵습니다. 충분한 훈련 데이터, 전문 지식, 출력을 검증할 방법이 필요합니다. ONESTRUCTION, Inc.는 openBIM을 통해 업계 문제를 해결하는 건설 기술 스타트업입니다. GenAIIC의 기술 자문을 받아 전문 기반 모델(FM)인 Ishigaki-IDS를 구축했습니다.

---

### 3. 🎯 직무별 실전 활용 팁

* **👩‍💻 개발자**: 최신 AI 모델 아키텍처 및 API 연동 방식을 현재 개발 스택에 적용해 보세요.
