INSERT OR REPLACE INTO trend_news (
  id, title, report_type, executive_summary, analytical_deep_dive,
  key_takeaways, original_sources, tags, matched_lenses
) VALUES (
  '25580eb8-44ac-5c05-936f-c6119480c3f5',
  'GeForce NOW, 26개의 새로운 게임으로 8월을 뒤흔들다',
  '빅테크 공식',
  '8월이 다가왔습니다. GeForce NOW 회원을 위한 26개의 새로운 게임이 출시되었습니다. World of Warships: Legends에서 바다를 지휘하고 이번 주에 새로 추가된 8개 게임을 시작으로 GeForce NOW 라이브러리의 다음 콘텐츠를 알아보세요. 또한, GeForce NOW는 이번 주 텍사스 그레이프바인에서 열리는 QuakeCon 게임 컨퍼런스에 참석하여 참석자들을 기다리고 있는 실습 경험을 제공합니다. QuakeCon으로 돌아오기 QuakeCon의 NVIDIA 부스를 방문하여 GeForce RTX 5080 기반 Ultimate 클라우드 게임을 실제로 경험해 보세요. 데모를 통해 울트라와이드 디스플레이에서 초당 최대 5K 120프레임의 놀라운 비주얼과 끊김없는 끊김 없는 성능을 확인할 수 있습니다.',
  '# 📌 [Technical Report] GeForce NOW, 26개의 새로운 게임으로 8월을 뒤흔들다

> **주요 출처**: NVIDIA AI Blog | **카테고리**: 빅테크 공식 | **검증**: ✅ AI Trend News

---

### 1. 📌 핵심 요약

GeForce NOW 회원을 위한 26개의 새로운 게임이 출시되었습니다.

World of Warships: Legends에서 바다를 지휘하고 이번 주에 새로 추가된 8개 게임을 시작으로 GeForce NOW 라이브러리의 다음 콘텐츠를 알아보세요.

