  'IT 매체',
  '인공 지능 코딩 혁명에는 비용이 많이 든다는 단점이 있습니다. 코드를 자율적으로 작성, 디버깅 및 배포할 수 있는 Anthropic의 터미널 기반 AI 에이전트인 Claude Code는 전 세계 소프트웨어 개발자의 상상력을 사로잡았습니다. 그러나 사용량에 따라 월 20달러에서 200달러에 이르는 가격은 이 서비스를 제공하려는 프로그래머들 사이에서 점점 커지는 반란을 촉발시켰습니다. 이제 무료 대안이 주목을 받고 있습니다. Block(구 Square로 알려진 금융 기술 회사)이 개발한 오픈 소스 AI 에이전트인 Goose는 Cla와 거의 동일한 기능을 제공합니다.',
  '# 📌 [Technical Report] Claude Code의 비용은 한 달에 최대 $200입니다. Goose는 동일한 작업을 무료로 수행합니다.

