  'dd840dae-b4c7-5c28-8f93-9cd6e22ebc1c',
  'Listen Labs는 AI 고객 인터뷰를 확대하기 위해 바이럴 빌보드 채용 스턴트를 통해 6900만 달러를 모금했습니다.',
  'IT 매체',
  'Alfred Wahlforss에게는 선택의 여지가 부족했습니다. 그의 스타트업인 Listen Labs는 100명이 넘는 엔지니어를 고용해야 했지만 Mark Zuckerberg의 1억 달러 제안과 경쟁하는 것은 불가능해 보였습니다. 그래서 그는 샌프란시스코의 한 광고판에 마케팅 예산의 5분의 1인 5,000달러를 지출했습니다. 이 광고판에는 횡설수설처럼 보이는 다섯 개의 난수 문자열이 표시되어 있었습니다. 숫자는 실제로 AI 토큰이었습니다. 디코딩된 그들은 코딩 과제로 이어졌습니다. 문 앞에 있는 거의 모든 사람을 거부하는 것으로 유명한 베를린 나이트클럽인 Berghain에서 디지털 경비원 역할을 하는 알고리즘을 구축하는 것입니다. 며칠 만에 수천 명이 퍼즐을 풀려고 시도했습니다. 43',
  '# 📌 [Technical Report] Listen Labs는 AI 고객 인터뷰를 확대하기 위해 바이럴 빌보드 채용 스턴트를 통해 6900만 달러를 모금했습니다.

> **주요 출처**: VentureBeat AI | **카테고리**: IT 매체 | **검증**: ✅ AI Trend News

---

