그의 스타트업인 Listen Labs는 100명이 넘는 엔지니어를 고용해야 했지만 Mark Zuckerberg의 1억 달러 제안과 경쟁하는 것은 불가능해 보였습니다.

그래서 그는 샌프란시스코의 한 광고판에 마케팅 예산의 5분의 1인 5,000달러를 지출했습니다.

---

