  '["세일즈포스(Salesforce)는 화요일 회사의 업무 보조자인 슬랙봇(Slackbot)의 완전히 재구축된 버전을 출시했습니다.", "이 버전은 단순한 알림 도구에서 경영진이 설명하는 엔터프라이즈 데이터 검색, 문서 초안 작성 및 직원을 대신하여 조치를 취할 수 있는 완전한 기능의 AI 에이전트로 변환되었습니다.", "현재 Business+ 및 Enterprise+ 고객에게 일반적으로 제공되는 새로운 Slackbot은 소프트웨어 에이전트가 인간과 함께 복잡한 작업을 완료하는 신흥 \"에이전트 AI\" 운동의 중심에 Slack을 배치하려는 Salesforce의 가장 공격적인 움직임입니다."]',
  '[{"title": "VentureBeat AI", "url": "https://venturebeat.com/technology/salesforce-rolls-out-new-slackbot-ai-agent-as-it-battles-microsoft-and"}]',
  '["#AI트렌드", "#VentureBeatAI"]',
