* **🔬 연구자**: 관련 벤치마크 데이터 및 논문 원문을 교차 검증하세요.
',
  '["Anthropic은 월요일에 큰 성공을 거둔 Claude Code 도구의 기능을 비기술적인 사용자에게도 확장하는 새로운 AI 에이전트 기능인 Cowork를 출시했습니다.", "회사 내부자에 따르면 팀은 주로 Claude Code 자체를 사용하여 약 1주일 반 만에 전체 기능을 구축했습니다.", "이번 출시는 실용적인 AI 에이전트를 주류 사용자에게 제공하기 위한 경쟁에서 중요한 변곡점을 의미하며, Anthropic은 대화형 AI 분야에서 OpenAI 및 Google뿐만 아니라 AI 기반 생산성 도구의 급성장하는 시장에서 Microsoft의 Copilot과도 경쟁할 수 있는 입지를 마련했습니다."]',
