INSERT OR REPLACE INTO trend_news (
  id, title, report_type, executive_summary, analytical_deep_dive,
  key_takeaways, original_sources, tags, matched_lenses
) VALUES (
  'cfbabe21-2201-5b91-8ec7-cac3beed4893',
  '대규모 공급망 공격으로 테라바이트 규모의 자격 증명 유출',
  'IT 매체',
  'AI 기반 소프트웨어 개발을 간소화하는 오픈 소스 도구인 LiteLLM에 대한 공급망 공격으로 인해 세계에서 가장 크고 가장 민감한 조직에 속한 테라바이트 규모의 자격 증명이 노출되었습니다. Microsoft, Amazon, Cisco, Samsung, Salesforce는 액세스 비밀이 노출된 소수의 기업일 뿐입니다. 이 폭로는 보안 회사인 CloudSEK와 Hudson Rock에 의해 화요일과 수요일에 게시되었습니다. CloudSEK는 클라우드 키, 저장소 토큰, SSH 키, Kubernetes 비밀, 패키지 게시 자격 증명, 환경 변수 및 AI 공급자 ke를 발견했다고 밝혔습니다.',
  '# 📌 [Technical Report] 대규모 공급망 공격으로 테라바이트 규모의 자격 증명 유출

> **주요 출처**: Ars Technica AI | **카테고리**: IT 매체 | **검증**: ✅ AI Trend News

---

### 1. 📌 핵심 요약

AI 기반 소프트웨어 개발을 간소화하는 오픈 소스 도구인 LiteLLM에 대한 공급망 공격으로 인해 세계에서 가장 크고 가장 민감한 조직에 속한 테라바이트 규모의 자격 증명이 노출되었습니다.

Microsoft, Amazon, Cisco, Samsung, Salesforce는 액세스 비밀이 노출된 소수의 기업일 뿐입니다.

이 폭로는 보안 회사인 CloudSEK와 Hudson Rock에 의해 화요일과 수요일에 게시되었습니다.

---

### 2. 🔍 배경 및 의미

AI 기반 소프트웨어 개발을 간소화하는 오픈 소스 도구인 LiteLLM에 대한 공급망 공격으로 인해 세계에서 가장 크고 가장 민감한 조직에 속한 테라바이트 규모의 자격 증명이 노출되었습니다. Microsoft, Amazon, Cisco, Samsung, Salesforce는 액세스 비밀이 노출된 소수의 기업일 뿐입니다. 이 폭로는 보안 회사인 CloudSEK와 Hudson Rock에 의해 화요일과 수요일에 게시되었습니다. CloudSEK는 클라우드 키, 저장소 토큰, SSH 키, Kubernetes 비밀, 패키지 게시 자격 증명, 환경 변수 및 AI 공급자 ke를 발견했다고 밝혔습니다.

---

### 3. 🎯 직무별 실전 활용 팁

* **👩‍💻 개발자**: 최신 AI 모델 아키텍처 및 API 연동 방식을 현재 개발 스택에 적용해 보세요.
* **💡 기획자/PM**: 서비스 로드맵에 AI 기술 트렌드를 반영한 사용자 경험을 기획하세요.
* **💼 비즈니스**: 고비용 상용 API를 오픈소스 모델로 대체하여 TCO를 최적화하세요.
* **🔬 연구자**: 관련 벤치마크 데이터 및 논문 원문을 교차 검증하세요.
',
  '["AI 기반 소프트웨어 개발을 간소화하는 오픈 소스 도구인 LiteLLM에 대한 공급망 공격으로 인해 세계에서 가장 크고 가장 민감한 조직에 속한 테라바이트 규모의 자격 증명이 노출되었습니다.", "Microsoft, Amazon, Cisco, Samsung, Salesforce는 액세스 비밀이 노출된 소수의 기업일 뿐입니다.", "이 폭로는 보안 회사인 CloudSEK와 Hudson Rock에 의해 화요일과 수요일에 게시되었습니다."]',
  '[{"title": "Ars Technica AI", "url": "https://arstechnica.com/security/2026/08/terabytes-of-credentials-leaked-in-massive-supply-chain-attack/"}]',
