INSERT OR REPLACE INTO trend_news (
  id, title, report_type, executive_summary, analytical_deep_dive,
  key_takeaways, original_sources, tags, matched_lenses
) VALUES (
  'f9d62c86-e22f-5c9c-9823-9bb682bcc95e',
  'Twitch 콘텐츠는 수년 동안 Amazon AI를 훈련해 왔지만 이제 사용자는 훈련을 중단할 수 있습니다.',
  'IT 매체',
  '이제 Twitch에서는 Amazon의 "생성 AI 콘텐츠 모델"을 교육하기 위해 Amazon이 자신의 채널에서 콘텐츠를 사용하는 것을 사용자가 거부할 수 있습니다. 오늘 발표된 이러한 변화는 회사 임원이 Amazon이 AI 교육을 위해 Twitch 콘텐츠를 사용하고 있음을 확인한 지 2년 이상이 지난 후에 나온 것입니다. 업데이트된 지원 페이지에서 Twitch는 사용자가 "텍스트, 오디오, 이미지 또는 비디오를 생성하거나 합성하는 것이 목적인 Amazon에서 개발한 모델의 향후 교육에 사용되는 스트림, VOD, 클립, 스트림 채팅, 채널의 사진 및 텍스트"를 원하지 않는 경우 선택을 취소해야 함을 확인합니다. 선택 해제하려면 사용자는 다음을 수행해야 합니다.',
  '# 📌 [Technical Report] Twitch 콘텐츠는 수년 동안 Amazon AI를 훈련해 왔지만 이제 사용자는 훈련을 중단할 수 있습니다.

> **주요 출처**: Ars Technica AI | **카테고리**: IT 매체 | **검증**: ✅ AI Trend News

