',
  '["Meta는 개방형 대형 언어 모델에 중점을 두겠다는 의도를 발표했습니다.", "또한 회사는 Muse Glimmer라는 개방형 모델을 출시하고 앞으로 몇 주 안에 더욱 강력한 모델인 Muse Spark 1.2의 무게를 공개하겠다고 약속했습니다.", "이러한 발표와 함께 Meta CEO인 Mark Zuckerberg는 앞으로 나아갈 AI 시스템 및 거버넌스에 대한 회사의 철학을 설명하는 6,000자 이상의 에세이를 발표했습니다."]',
