* **🔬 연구자**: 관련 벤치마크 데이터 및 논문 원문을 교차 검증하세요.
',
  '["OpenAI의 곧 출시될 스마트 스피커의 가격은 아마도 300달러가 넘을 것이라고 Bloomberg의 Mark Gurman에 \"이 문제에 정통한 사람들\"이 말했습니다.", "7월부터 아직 발표되지 않은 스마트 스피커에 대해 보도해온 블룸버그(Bloomberg)는 오늘 생성 AI 회사가 최대 400달러의 충전을 \"논의\"했다고 밝혔습니다.", "이 출판물은 OpenAI가 스마트 스피커를 스마트폰 대체품으로 보고 있다고 밝혔습니다."]',
  '[{"title": "Ars Technica AI", "url": "https://arstechnica.com/gadgets/2026/08/openais-expensive-smart-speaker-will-use-moving-parts-to-seem-more-alive/"}]',
