  'IT 매체',
  '올 여름 초, 거의 160,000명의 지원자가 멕시코 최대 대학인 UNAM 입학 시험에 응시했습니다. 처음으로 그들은 5월 말부터 6월 초까지 몇 주에 걸쳐 "잠금" 브라우저와 AI 기반 웹캠 감독 소프트웨어를 사용하여 완전히 원격으로 수행했습니다. 그것은 재앙이었습니다. 시험 결과가 나왔을 때 특히 상위권에서는 과거 결과와 거의 유사하지 않았습니다. 2021년부터 2025년 사이에 응시자의 3.5%가 120개 문항으로 구성된 UNAM 시험에서 100점 이상을 받았습니다. 올해는 16.3%가 그렇게 했다. 전체 기사 읽기 댓글',
