) VALUES (
  '56d2e599-c6e1-5066-8b79-fbf1f1555e71',
  '아이들이 AI에 대해 어떻게 생각하는지 직접 표현해 보세요.',
  'IT 매체',
  '우리가 아이들에게 인공지능에 관해 이야기하려고 했을 때, 우리는 무엇을 듣게 될지 안다고 생각했습니다. 우리는 밀레니얼 세대와 X세대가 CliffsNotes를 열거나 TI-82에 공식을 프로그래밍한 방식처럼 약간의 속임수를 쓰기 위해 그것을 사용하고 있다고 말하는 사람도 있고, 이를 사용하는 영감을 주는 방법을 공유하는 사람도 있을 것으로 예상했습니다. 우리는 또한 딥페이크나 직장 파괴와 같이 어린이에게 덜 국한된 우려 사항에 대해서도 귀를 기울였습니다. 하지만 10~18세 어린이에게 AI에 대해 물었을 때 실제로 들은 내용에는 미묘한 차이가 있었습니다. 음악, 암벽등반, 축구에 대해 계속 이야기할 수 있는 많은 아이들이 우리의 질문을 만났습니다.',
  '# 📌 [Technical Report] 아이들이 AI에 대해 어떻게 생각하는지 직접 표현해 보세요.

> **주요 출처**: MIT Tech Review | **카테고리**: IT 매체 | **검증**: ✅ AI Trend News

---

### 1. 📌 핵심 요약

우리가 아이들에게 인공지능에 관해 이야기하려고 했을 때, 우리는 무엇을 듣게 될지 안다고 생각했습니다.

우리는 밀레니얼 세대와 X세대가 CliffsNotes를 열거나 TI-82에 공식을 프로그래밍한 방식처럼 약간의 속임수를 쓰기 위해 그것을 사용하고 있다고 말하는 사람도 있고, 이를 사용하는 영감을 주는 방법을 공유하는 사람도 있을 것으로 예상했습니다.

우리는 또한 딥페이크나 직장 파괴와 같이 어린이에게 덜 국한된 우려 사항에 대해서도 귀를 기울였습니다.

---

### 2. 🔍 배경 및 의미

우리가 아이들에게 인공지능에 관해 이야기하려고 했을 때, 우리는 무엇을 듣게 될지 안다고 생각했습니다. 우리는 밀레니얼 세대와 X세대가 CliffsNotes를 열거나 TI-82에 공식을 프로그래밍한 방식처럼 약간의 속임수를 쓰기 위해 그것을 사용하고 있다고 말하는 사람도 있고, 이를 사용하는 영감을 주는 방법을 공유하는 사람도 있을 것으로 예상했습니다. 우리는 또한 딥페이크나 직장 파괴와 같이 어린이에게 덜 국한된 우려 사항에 대해서도 귀를 기울였습니다. 하지만 10~18세 어린이에게 AI에 대해 물었을 때 실제로 들은 내용에는 미묘한 차이가 있었습니다. 음악, 암벽등반, 축구에 대해 계속 이야기할 수 있는 많은 아이들이 우리의 질문을 만났습니다.

