* **🔬 연구자**: 관련 벤치마크 데이터 및 논문 원문을 교차 검증하세요.
',
  '["우리가 아이들에게 인공지능에 관해 이야기하려고 했을 때, 우리는 무엇을 듣게 될지 안다고 생각했습니다.", "우리는 밀레니얼 세대와 X세대가 CliffsNotes를 열거나 TI-82에 공식을 프로그래밍한 방식처럼 약간의 속임수를 쓰기 위해 그것을 사용하고 있다고 말하는 사람도 있고, 이를 사용하는 영감을 주는 방법을 공유하는 사람도 있을 것으로 예상했습니다.", "우리는 또한 딥페이크나 직장 파괴와 같이 어린이에게 덜 국한된 우려 사항에 대해서도 귀를 기울였습니다."]',
  '[{"title": "MIT Tech Review", "url": "https://www.technologyreview.com/2026/08/13/1141410/how-kids-feel-about-ai-own-words/"}]',
