',
  '["이 이야기는 원래 AI에 관한 주간 뉴스레터인 The Algorithm에 게재되었습니다.", "먼저 받은 편지함에서 이와 같은 기사를 받으려면 여기에서 가입하세요.", "지난주에 저는 세계에서 가장 성취도가 높고 가장 유망한 AI 연구자들과 합류하기 위해 샌프란시스코에서 남쪽으로 30마일 떨어진 캘리포니아주 마운틴뷰에 있는 호텔로 향했습니다."]',
