  '주요 경제학자들이 서명한 공개 서한에서 AI가 당신의 일자리를 훔칠 수 있다고 경고하는 것은 충분히 안타까운 일입니다. 곧 저녁 식사를 준비하는 데 당신보다 나아질 수도 있다는 사실? 부상에 대한 모욕. 그러나 이것이 바로 1X가 7월 데모에서 새롭고 인상적인 손재주(어떤 사람들에게는 이상하게 섹시한?) 로봇 손 한 쌍을 선보였을 때 약속한 것입니다. 기술 커뮤니티는 육체가 없는 손의 매력에 대해 극명하게 분열되어 있지만 거의 모든 사람들이 몇 가지가 확실히 섹시하지 않다는 데 동의할 수 있습니다. Grok의 포르노 알약 번역 기능, Meta의 오싹한 안경(곧 더욱 소름끼칠 수 있음),',
