  '["이제 Twitch 사용자는 자신의 콘텐츠를 Amazon의 생성 AI 모델 훈련에 사용하는 것을 거부할 수 있습니다.", "옵트아웃은 Twitch 지원 페이지에 따르면 \"텍스트, 오디오, 이미지 또는 비디오를 생성하거나 합성하는 것이 목적인\" Amazon AI 모델의 \"향후 교육\"에 \"귀하의 스트림, VOD, 클립, 스트림 채팅, 채널의 사진 및 텍스트\"가 사용되지 않는다는 것을 의미합니다.", "캡션 및 안전 도구와 같은 기타 \"AI 지원\" 기능은 생성 AI 교육을 선택 해제한 경우에도 계속 작동합니다."]',
  '[{"title": "The Verge AI", "url": "https://www.theverge.com/tech/979112/twitch-streamers-can-now-opt-out-from-training-amazons-ai"}]',
  '["#AI트렌드", "#TheVergeAI"]',
  '["pm"]'
);
