) VALUES (
  'b494f423-de0c-5f3d-aaea-6f0ae1fe07ad',
  'Sabre는 Rideshare Stimulator의 작성자를 ChatGPT로 교체하는 것을 거부합니다.',
  'IT 매체',
  '이전 수석 작가가 Saber가 "나를 ChatGPT로 대체했다"고 주장한 후 CEO Matthew Karch는 이제 Unigine이 개발한 지난 달 발표된 Rideshare "Stimulator" 게임에 대해 "Saber나 Unigine 모두 작가를 AI로 대체하지 않았습니다"라고 주장합니다. 그러나 작가인 Stella Sacco는 Bluesky에 "제가 이 작품의 수석 작가였습니다! 그리고 Sabre는 개발 중간에 나를 ChatGPT로 대체했습니다. 승객의 목소리도 모두 AI였습니다. 어느 시점에서 방향을 바꾸거나 Steam에 공개하지 않을 것입니다."라고 게시하면서 다르게 말합니다. Sabre는 Rideshare "Stimulator"를 "몰입형 운전"이라고 설명합니다.',
  '# 📌 [Technical Report] Sabre는 Rideshare Stimulator의 작성자를 ChatGPT로 교체하는 것을 거부합니다.

> **주요 출처**: The Verge AI | **카테고리**: IT 매체 | **검증**: ✅ AI Trend News

---

### 1. 📌 핵심 요약

이전 수석 작가가 Saber가 "나를 ChatGPT로 대체했다"고 주장한 후 CEO Matthew Karch는 이제 Unigine이 개발한 지난 달 발표된 Rideshare "Stimulator" 게임에 대해 "Saber나 Unigine 모두 작가를 AI로 대체하지 않았습니다"라고 주장합니다.

그러나 작가인 Stella Sacco는 Bluesky에 "제가 이 작품의 수석 작가였습니다.

그리고 Sabre는 개발 중간에 나를 ChatGPT로 대체했습니다.

---

### 2. 🔍 배경 및 의미

이전 수석 작가가 Saber가 "나를 ChatGPT로 대체했다"고 주장한 후 CEO Matthew Karch는 이제 Unigine이 개발한 지난 달 발표된 Rideshare "Stimulator" 게임에 대해 "Saber나 Unigine 모두 작가를 AI로 대체하지 않았습니다"라고 주장합니다. 그러나 작가인 Stella Sacco는 Bluesky에 "제가 이 작품의 수석 작가였습니다! 그리고 Sabre는 개발 중간에 나를 ChatGPT로 대체했습니다. 승객의 목소리도 모두 AI였습니다. 어느 시점에서 방향을 바꾸거나 Steam에 공개하지 않을 것입니다."라고 게시하면서 다르게 말합니다. Sabre는 Rideshare "Stimulator"를 "몰입형 운전"이라고 설명합니다.

---

