',
  '["이전 수석 작가가 Saber가 \"나를 ChatGPT로 대체했다\"고 주장한 후 CEO Matthew Karch는 이제 Unigine이 개발한 지난 달 발표된 Rideshare \"Stimulator\" 게임에 대해 \"Saber나 Unigine 모두 작가를 AI로 대체하지 않았습니다\"라고 주장합니다.", "그러나 작가인 Stella Sacco는 Bluesky에 \"제가 이 작품의 수석 작가였습니다.", "그리고 Sabre는 개발 중간에 나를 ChatGPT로 대체했습니다."]',
