그러나 파키스탄에서는 판사를 위해 특별히 설계된 AI 도구를 대규모로 시험해 본 결과 적절한 훈련과 함께 이 기술이 판결의 질을 명백하게 저하시키지 않으면서 사건 해결 건수를 6.3% 증가시키는 것으로 나타났습니다.

