',
  '["전 세계의 심사위원들이 업무에 생성 AI를 불법적으로 사용했다는 이유로 헤드라인을 장식했습니다.", "그러나 파키스탄에서는 판사를 위해 특별히 설계된 AI 도구를 대규모로 시험해 본 결과 적절한 훈련과 함께 이 기술이 판결의 질을 명백하게 저하시키지 않으면서 사건 해결 건수를 6.3% 증가시키는 것으로 나타났습니다.", "처리량이 226만 건에 달하고 판사 수가 10만 명당 2명 미만(EU의 경우 22명, 브라질의 경우 8명)으로 파키스탄 사법부는 도움이 절실히 필요했습니다."]',
