  '["지금까지 구축된 시스템 중 가장 크고 복잡한 시스템 중 하나인 오늘날의 미국 전력망은 한계에 도달해 작동하고 있습니다.", "미국 에너지부에 따르면 급속한 산업 성장, 더욱 빈번해지는 기상 이변, 기록적인 전력 사용량 급증 등으로 인해 전력망이 한계점에 이르렀다고 합니다.", "대부분의 전력이 중앙 집중식 석탄 또는 가스 발전소에서 나오고 전기 사용량이 꾸준한 속도로 증가하는 보다 예측 가능한 세상을 위해 수십 년 전에 구축된 그리드는 부분적으로 데이터 센터의 수요 증가로 인해 예상치 못한 부담에 직면해 있습니다."]',
