INSERT OR REPLACE INTO trend_news (
  id, title, report_type, executive_summary, analytical_deep_dive,
  key_takeaways, original_sources, tags, matched_lenses
) VALUES (
  'b48f71b8-abb8-55a5-b006-cc3c48742dac',
  '연구자들은 사람 대신 AI에 대한 논문을 써야 할까요?',
  'IT 매체',
  '올해 5월, 대략 24개 최고 대학과 기술 기업의 연구자 37명이 ArXiv에 논문을 게재하여 과학자들이 논문 작성을 중단해야 한다고 주장했습니다. 왜? 인공지능은 다른 형식이 필요하고, AI의 요구가 우선되어야 한다고 말합니다. "AI 에이전트는 인간을 지원하는 도구가 아니라 과학 작업을 읽고, 재생산하고 확장하는 자율적인 기여자가 연구 워크플로의 일류 참가자가 되고 있습니다. 이러한 전환에는 처음부터 에이전트를 중심으로 구축된 인프라가 필요합니다."라고 저자는 "The Last Human"이라는 도발적인 기사에서 썼습니다.',
  '# 📌 [Technical Report] 연구자들은 사람 대신 AI에 대한 논문을 써야 할까요?

> **주요 출처**: IEEE Spectrum AI | **카테고리**: IT 매체 | **검증**: ✅ AI Trend News

---

### 1. 📌 핵심 요약

올해 5월, 대략 24개 최고 대학과 기술 기업의 연구자 37명이 ArXiv에 논문을 게재하여 과학자들이 논문 작성을 중단해야 한다고 주장했습니다.

인공지능은 다른 형식이 필요하고, AI의 요구가 우선되어야 한다고 말합니다.

"AI 에이전트는 인간을 지원하는 도구가 아니라 과학 작업을 읽고, 재생산하고 확장하는 자율적인 기여자가 연구 워크플로의 일류 참가자가 되고 있습니다.

---

### 2. 🔍 배경 및 의미

올해 5월, 대략 24개 최고 대학과 기술 기업의 연구자 37명이 ArXiv에 논문을 게재하여 과학자들이 논문 작성을 중단해야 한다고 주장했습니다. 왜? 인공지능은 다른 형식이 필요하고, AI의 요구가 우선되어야 한다고 말합니다. "AI 에이전트는 인간을 지원하는 도구가 아니라 과학 작업을 읽고, 재생산하고 확장하는 자율적인 기여자가 연구 워크플로의 일류 참가자가 되고 있습니다. 이러한 전환에는 처음부터 에이전트를 중심으로 구축된 인프라가 필요합니다."라고 저자는 "The Last Human"이라는 도발적인 기사에서 썼습니다.

---

### 3. 🎯 직무별 실전 활용 팁

* **👩‍💻 개발자**: 최신 AI 모델 아키텍처 및 API 연동 방식을 현재 개발 스택에 적용해 보세요.
* **💡 기획자/PM**: 서비스 로드맵에 AI 기술 트렌드를 반영한 사용자 경험을 기획하세요.
* **💼 비즈니스**: 고비용 상용 API를 오픈소스 모델로 대체하여 TCO를 최적화하세요.
* **🔬 연구자**: 관련 벤치마크 데이터 및 논문 원문을 교차 검증하세요.
',
  '["올해 5월, 대략 24개 최고 대학과 기술 기업의 연구자 37명이 ArXiv에 논문을 게재하여 과학자들이 논문 작성을 중단해야 한다고 주장했습니다.", "인공지능은 다른 형식이 필요하고, AI의 요구가 우선되어야 한다고 말합니다.", "\"AI 에이전트는 인간을 지원하는 도구가 아니라 과학 작업을 읽고, 재생산하고 확장하는 자율적인 기여자가 연구 워크플로의 일류 참가자가 되고 있습니다."]',
  '[{"title": "IEEE Spectrum AI", "url": "https://spectrum.ieee.org/ai-scientist-research-paper-format"}]',
  '["#AI트렌드", "#IEEESpectrumAI"]',
  '["researcher", "agent"]'
);
INSERT OR REPLACE INTO trend_news (
  id, title, report_type, executive_summary, analytical_deep_dive,
  key_takeaways, original_sources, tags, matched_lenses
) VALUES (
  '435ce71d-7058-5fb6-8f34-ed43dfad4863',
  '광범위한 AI 채택에도 불구하고 R&D 낭비가 지속되는 이유',
  'IT 매체',
  '이 보고서는 R&D 낭비를 조사하고 AI 채택이 결과적인 결정을 내리는 데 필요한 지능을 어떻게 앞지르는지 살펴봅니다. 참석자들이 배울 내용 R&D 예산이 손실된 곳. 3분의 1 이상의 조직이 시장에 진출하지 못한 프로젝트에 R&D 예산의 25~40%를 지출합니다. 프로젝트가 늦게 실패하는 이유 거의 절반의 팀이 개발 또는 테스트 중에 중단된 각 프로젝트에 대해 투자 낭비가 백만 달러 이상일 것으로 추정합니다. AI 채택이 격차를 해소하지 못한 이유. 대부분의 조직은 의사결정 지원보다는 데이터 분석, 모델링 등 실행 업무에 AI를 적용한다.',
  '# 📌 [Technical Report] 광범위한 AI 채택에도 불구하고 R&D 낭비가 지속되는 이유

> **주요 출처**: IEEE Spectrum AI | **카테고리**: IT 매체 | **검증**: ✅ AI Trend News

---

### 1. 📌 핵심 요약

이 보고서는 R&D 낭비를 조사하고 AI 채택이 결과적인 결정을 내리는 데 필요한 지능을 어떻게 앞지르는지 살펴봅니다.

참석자들이 배울 내용 R&D 예산이 손실된 곳.

3분의 1 이상의 조직이 시장에 진출하지 못한 프로젝트에 R&D 예산의 25~40%를 지출합니다.

---

### 2. 🔍 배경 및 의미

이 보고서는 R&D 낭비를 조사하고 AI 채택이 결과적인 결정을 내리는 데 필요한 지능을 어떻게 앞지르는지 살펴봅니다. 참석자들이 배울 내용 R&D 예산이 손실된 곳. 3분의 1 이상의 조직이 시장에 진출하지 못한 프로젝트에 R&D 예산의 25~40%를 지출합니다. 프로젝트가 늦게 실패하는 이유 거의 절반의 팀이 개발 또는 테스트 중에 중단된 각 프로젝트에 대해 투자 낭비가 백만 달러 이상일 것으로 추정합니다. AI 채택이 격차를 해소하지 못한 이유. 대부분의 조직은 의사결정 지원보다는 데이터 분석, 모델링 등 실행 업무에 AI를 적용한다.

---

### 3. 🎯 직무별 실전 활용 팁

* **👩‍💻 개발자**: 최신 AI 모델 아키텍처 및 API 연동 방식을 현재 개발 스택에 적용해 보세요.
* **💡 기획자/PM**: 서비스 로드맵에 AI 기술 트렌드를 반영한 사용자 경험을 기획하세요.
* **💼 비즈니스**: 고비용 상용 API를 오픈소스 모델로 대체하여 TCO를 최적화하세요.
* **🔬 연구자**: 관련 벤치마크 데이터 및 논문 원문을 교차 검증하세요.
',
  '["이 보고서는 R&D 낭비를 조사하고 AI 채택이 결과적인 결정을 내리는 데 필요한 지능을 어떻게 앞지르는지 살펴봅니다.", "참석자들이 배울 내용 R&D 예산이 손실된 곳.", "3분의 1 이상의 조직이 시장에 진출하지 못한 프로젝트에 R&D 예산의 25~40%를 지출합니다."]',
