  '다이나 로보틱스(Dyna Robotics)가 로봇 조작을 위한 월드 액션 모델인 Dyna-2를 출시했습니다. 100만 시간이 넘는 자기 중심적인 인간 비디오를 바탕으로 사전 훈련되었습니다. 그것은 대략 170년 동안 계속해서 깨어 있는 경험을 한 것입니다. 로봇 학습은 원격 조작이 의도적으로 생성해야 하는 작업 레이블이 지정된 데이터로 인해 병목 현상이 발생했습니다. Dyna-2는 일반 인간 영상이 대체할 수 있는지 테스트합니다. 연구팀은 데이터 사다리를 1,000시간에서 1,000,000시간까지 훈련하고 어느 정도 규모인지 측정했습니다. 세 가지 결과는 다음과 같습니다: 인간 데이터에 대한 확장 법칙, 해당 법칙을 보이지 않는 로봇 데이터로 처음으로 전송, 그리고 그에 대한 증거',
  '# 📌 [Technical Report] Dyna Robotics, Dyna-2 출시: 100만 시간의 인간 비디오로 사전 훈련된 월드 액션 모델

