  'c408e9b5-8e57-5f6e-b56c-422627055c65',
  'NVIDIA AI Releases Nemotron 3.5 Lightning: A 30B Open MoE with 3B Active Parameters, and NeMo Switchyard Model Router',
  'IT 매체',
  'NVIDIA는 특수 모델의 시스템에서 상시 실행되는 AI 에이전트를 구축하기 위한 개방형 기술을 도입했습니다. 두 개의 아티팩트가 함께 배송되었습니다. Nemotron 3.5 Lightning은 대용량 에이전트 작업을 위해 제작된 가볍고 사용자 정의 가능한 개방형 모델이며, NeMo Switchyard는 에이전트 워크플로의 각 단계를 가장 유능하고 효율적인 모델로 안내하는 오픈 소스 라우팅 라이브러리입니다. 두 가지 모두 해결하는 문제는 구조적입니다. 장기 실행 에이전트는 도구 호출, 결과 검증 및 하위 에이전트 위임에 대부분의 시간을 보내고 이러한 모든 단계를 프론티어 추론 모델로 보냅니다.',
  '# 📌 [Technical Report] NVIDIA AI Releases Nemotron 3.5 Lightning: A 30B Open MoE with 3B Active Parameters, and NeMo Switchyard Model Router

> **주요 출처**: MarkTechPost AI | **카테고리**: IT 매체 | **검증**: ✅ AI Trend News

---

### 1. 📌 핵심 요약

NVIDIA는 특수 모델의 시스템에서 상시 실행되는 AI 에이전트를 구축하기 위한 개방형 기술을 도입했습니다.

두 개의 아티팩트가 함께 배송되었습니다.

Nemotron 3.5 Lightning은 대용량 에이전트 작업을 위해 제작된 가볍고 사용자 정의 가능한 개방형 모델이며, NeMo Switchyard는 에이전트 워크플로의 각 단계를 가장 유능하고 효율적인 모델로 안내하는 오픈 소스 라우팅 라이브러리입니다.

---

### 2. 🔍 배경 및 의미

