---

### 1. 📌 핵심 요약

물체 제거 모델은 이를 판단하는 데 사용되는 측정 기준보다 빠르게 개선되었습니다.

이제 확산 지우개는 그림자, 반사 및 폐색된 구조를 확실하게 재구성하지만 PSNR, SSIM, LPIPS, ReMOVE 및 CFD는 종종 출력 순위를 잘못된 방식으로 지정합니다.

삭제는 잘못된 일대다 작업이므로 비교할 단일 기준 진실이 존재하지 않습니다.

