  '11404a25-dc1f-59bb-bd08-64914127da4b',
  'webAI, TwIL-LM 출시: 로컬 하드웨어에서 자동 형식화를 위한 1.7B 및 3B 형식 논리 모델 제품군',
  'IT 매체',
  'webAI는 1.7B 및 3B 매개변수의 두 가지 형식 논리 추론기 모델 제품군인 TwIL-LM을 출시했습니다. 3B 멤버인 TwIL-LM3은 SmolLM3-3B의 병합된 미세 조정입니다. 1.7B 멤버는 SmolLM2-1.7B-Instruct용 PEFT LoRA 어댑터입니다. 두 가지 목표 자동 형식화: 영어를 1차 논리로 번역하고 전제에서 결론이 나오는지 확인합니다. 둘 다 1.7B의 경우 1.06GB 양자화 빌드, 3B의 경우 1.78GiB Q4_K_M GGUF로 로컬에서 실행됩니다. webAI의 발표는 5개의 형식적 추론 레인 중 4개에서 gpt-oss-120b를 능가하는 릴리스를 중심으로 구성되었습니다. 배포 가능합니까? 부분',
  '# 📌 [Technical Report] webAI, TwIL-LM 출시: 로컬 하드웨어에서 자동 형식화를 위한 1.7B 및 3B 형식 논리 모델 제품군

