  'IT 매체',
  'Meta는 Muse Spark에서 추출한 300억 매개변수 다중 모드 모델인 Muse Glimmer를 출시했습니다. 상시 로컬 에이전트 워크플로에 맞게 조정되었으며 Apache 2.0으로 제공됩니다. 30B 모델에는 일반적으로 최대 정밀도로 55GB 이상의 메모리가 필요합니다. Meta는 이를 대략 4비트로 압축한 다음 블록 수준 추측 디코딩을 추가하여 실제 에이전트 루프 내에 있을 수 있을 만큼 빠르게 응답합니다. 결과는 네트워크 호출 없이 하나의 소비자 GPU 또는 Mac에서 실행됩니다. 배포 가능합니까? 예, 가중치는 Apache 2.0에서 공개됩니다. Hugging Face 컬렉션에는 BF16 가중치, GGUF k-Quants, ExecuTorch 빌드,',
