  'c7599694-1cc0-5188-b9fc-27a8c3ea0789',
  '더 좋고, 더 빠르고, 더 강력합니다: 프로그래밍 방식 기술 학습으로 상담사 비용 절감 효과가 가장 좋습니다.',
  '연구/학계',
