  '연구/학계',
  'arXiv:2608.11254v1 태양광 발전을 현대 전력망에 안정적으로 통합하려면 정확한 태양 복사 조도 예측이 필수적입니다. 전천 이미저(ASI)는 구름에 대한 고해상도 관찰을 제공하므로 시간 내 예측에 매우 적합합니다. 최근의 딥 러닝 접근 방식은 예측 정확도를 크게 향상시켰지만 결정론적 예측과 램프 이벤트 예측 능력 저하로 인해 제한되는 경우가 많습니다. 이 연구에서는 잠재 공간 결합을 활용하여 task-aw를 학습하는 생성적 예측 프레임워크인 FarSky를 제안합니다.',
