  '연구/학계',
  'arXiv:2608.11256v1 기관에서는 학문적 무결성을 위해 상업용 AI 탐지기를 사용하지만 탐지기는 AI 편집과 전체 LLM 초안을 구별할 수 없으며 둘 다 위법 행위로 처리할 수 있습니다. 출판된 영어 초록(4개 도메인, 2013~2015년 vs. 2023~2025년)에 대한 통제된 연구에서 우리는 tau=0.50에서 프록시 인간/AI 라벨에 따라 이 정책 실패를 정량화합니다. 지침 준수 AI 지원을 위한 프록시인 가벼운 "추상만 수정" 편집은 64~80%(Pangram/GPTZero)로 표시됩니다. 수정되지 않은 2023~2025년 원본은 9~15%로 표시되며 비STEM 비율은 훨씬 높습니다.',
