  '무중력 미세 조정: Logit-Space Transport를 통한 LLM 개인화',
  '연구/학계',
  'arXiv:2608.11342v1 감독된 미세 조정(SFT)은 LLM을 대상 분포에 적용하기 위한 표준 접근 방식이지만 각 작성자가 별도의 가중치 액세스, 최적화, 저장 및 재교육이 필요한 개인화와 같은 설정에서는 비용이 엄청납니다. 우리는 가중치 업데이트 없이 SFT의 분포 효과를 근사화하는 훈련 없는 디코딩 시간 방법인 WFT(Weightless Fine-Tuning)를 제안합니다. WFT는 작성자의 훈련 시퀀스에 대한 지도 잔차를 계산하고 교차 접두사 전송을 통해 이를 현재 프롬프트로 전송합니다.',
  '# 📌 [Technical Report] 무중력 미세 조정: Logit-Space Transport를 통한 LLM 개인화

> **주요 출처**: ArXiv Machine Learning | **카테고리**: 연구/학계 | **검증**: ✅ AI Trend News

---

### 1. 📌 핵심 요약

arXiv:2608.11342v1 감독된 미세 조정(SFT)은 LLM을 대상 분포에 적용하기 위한 표준 접근 방식이지만 각 작성자가 별도의 가중치 액세스, 최적화, 저장 및 재교육이 필요한 개인화와 같은 설정에서는 비용이 엄청납니다.

우리는 가중치 업데이트 없이 SFT의 분포 효과를 근사화하는 훈련 없는 디코딩 시간 방법인 WFT(Weightless Fine-Tuning)를 제안합니다.

WFT는 작성자의 훈련 시퀀스에 대한 지도 잔차를 계산하고 교차 접두사 전송을 통해 이를 현재 프롬프트로 전송합니다..

